    const useAvailableTutorials = ()=>useTutorialContext().state.availableTutorials;
    const TutorialContext = reactExports.createContext(null);
    const TutorialProvider = ({ store, children })=>{
        const [state, setState] = reactExports.useState(store.snapshot());
        reactExports.useEffect(()=>{
            const unsubscribe = store.subscribe(()=>{
                setState(store.snapshot());
            });
            return unsubscribe;
        }, [
            store
        ]);
        reactExports.useEffect(()=>{
            const existingIds = new Set(state.availableTutorials.map((t)=>t.id));
            if (!existingIds.has(sketchpadTour.id)) {
                store.addTutorial(sketchpadTour);
            }
        }, [
            state.availableTutorials,
            store
        ]);
        return jsxRuntimeExports.jsx(TutorialContext.Provider, {
            value: {
                store,
                state
            },
            children
        });
    };
    const useTutorialContext = ()=>{
        const context = reactExports.useContext(TutorialContext);
        if (!context) throw new Error("Tutorial hooks must be used within TutorialProvider");
        return context;
    };
