                            const pairKey = piece.guid < otherNode.data.piece.guid ? `${piece.guid}::${otherNode.data.piece.guid}` : `${otherNode.data.piece.guid}::${piece.guid}`;
                            if (connectedPiecePairs.has(pairKey)) continue;
